import{_ as a,o as _,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2015Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2015Q1 Ceph社区季度进展报告","date":"2015-03-01T00:00:00.000Z","updated":"2015-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/2015Q1_Ceph社区季度总结.md","filePath":"posts/2015/2015Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2015/2015Q1_Ceph社区季度总结.md"};function t(s,e,l,o,D,m){return _(),r("div",null,[...e[0]||(e[0]=[n('<p>我将基于这31篇2015Q1季度的会议和视频总结，生成一份完整的社区季度进展报告。</p><h1 id="ceph-社区季度进展报告-—-2015-q1" tabindex="-1">Ceph 社区季度进展报告 — 2015 Q1 <a class="header-anchor" href="#ceph-社区季度进展报告-—-2015-q1" aria-label="Permalink to &quot;Ceph 社区季度进展报告 — 2015 Q1&quot;">​</a></h1><hr><h2 id="一、本季度重点议题" tabindex="-1">一、本季度重点议题 <a class="header-anchor" href="#一、本季度重点议题" aria-label="Permalink to &quot;一、本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区围绕以下几个核心方向展开了密集讨论：</p><p><strong>1. 新存储后端（NewStore / BlueStore 前身）</strong></p><p>OSD 存储后端的重构是本季度最受关注的议题之一。现有 FileStore 经过多年演进已趋于复杂，社区在 <a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Newstore.html">CDS_Infernalis_Day_2.2_--<em>OSD</em>-_Newstore</a>) 中深入讨论了以 RocksDB + POSIX 文件系统为基础的新存储后端方案，目标是消除双写开销、提升小写性能。</p><p><strong>2. RBD 异步镜像与灾难恢复</strong></p><p>RBD 跨集群异步复制是本季度 RBD 方向的核心议题，在 <a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RBD_-_Async_Mirroring.html">CDS_Infernalis_Day_1--<em>RBD</em>-_Async_Mirroring</a>) 中提出了基于完整日志的异步镜像设计方案，为灾难恢复能力奠定基础。</p><p><strong>3. RGW Active-Active 多区域架构</strong></p><p>RGW 的多区域主动架构改造在 <a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Active_Active_Arch.html">CDS_Infernalis_Day_1_--<em>RGW</em>-_Active_Active_Arch</a>) 中被重点讨论，涉及区域命名重构、同步代理改进、对象版本控制等多个子议题。</p><p><strong>4. Erasure Coding 覆盖写支持</strong></p><p>EC 池的覆盖写能力是制约 RBD 使用 EC 存储池的关键瓶颈，<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Erasure_Coding_Pool_Overwrite_Support.html">CDS_Infernalis_Day_1_--<em>OSD</em>-_Erasure_Coding_Pool_Overwrite_Support</a>) 对两阶段提交、回滚日志等多种方案进行了系统性评估。</p><p><strong>5. OSD 性能与延迟优化</strong></p><p>包括 pering 延迟、scrub 侵入性、I/O hints、Cache Tier 改进等多个性能子议题在本季度均有专项讨论。</p><hr><h2 id="二、技术亮点" tabindex="-1">二、技术亮点 <a class="header-anchor" href="#二、技术亮点" aria-label="Permalink to &quot;二、技术亮点&quot;">​</a></h2><h3 id="_2-1-rbd" tabindex="-1">2.1 RBD <a class="header-anchor" href="#_2-1-rbd" aria-label="Permalink to &quot;2.1 RBD&quot;">​</a></h3><ul><li><p><strong>异步镜像机制设计</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RBD_-_Async_Mirroring.html">CDS_Infernalis_Day_1_--<em>RBD</em>-_Async_Mirroring</a>) 提出基于 RBD journal 的完整数据日志方案，支持写回（writeback）和写透（writethrough）两种日志模式，可在单个镜像或整个存储池级别配置复制粒度，并支持一致性组（consistency group）。</p></li><li><p><strong>LibRBD 元数据机制</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Add_metadata_mechanism_to_LibRBD.html">CDS_Infernalis_Day_2.2_--<em>RBD</em>-_Add_metadatamechanism_to_LibRBD</a>) 讨论了为每个 RBD 镜像存储键值对元数据的方案，元数据存储于镜像头部，通过 <code>rbd meta put</code> / <code>rbd meta list</code> 等命令操作，解决不同场景下配置不一致的问题。</p></li><li><p><strong>内核 RBD 客户端 Copy-on-Read</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Kernel_RBD_client_supports_copy-on-read.html">CDS_Infernalis_Day_2.2_--<em>RBD</em>-_Kernel_RBD_client_supports_copy-on-read</a>) 讨论了使用状态机技术优化内核 RBD 的复制和写入操作，以及对象映射（object map）的哈希表优化方案。</p></li><li><p><strong>克隆与父卷差异导出</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_export_diff_between_clone_parent.html">CDS_Infernalis_Day_2.2_--<em>RBD</em>-_export_diff_between_clone_parent</a>) 讨论了 RBD 克隆与父卷之间差异导出功能，以及多对象事务的两阶段提交实现方案。</p></li><li><p><strong>Acelio XIO 传输协议集成</strong>：<a href="./CDS_Infernalis_Day_1_--_Acelio_XIO_Integration_with_kernel_RBD.html">CDS_Infernalis_Day_1_--_Accelio_XIO_Integration_with_kernel_RBD</a> 介绍了将高性能 XIO 传输协议集成到内核 RBD 客户端的工作，支持动态加载传输协议，TCP 作为默认选项保持兼容。</p></li><li><p><strong>集群化 SCSI Target</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Clustered_SCSI_Target_using_RBD.html">CDS_Infernalis_Day_1_--_Clustered_SCSI_Target_using_RBD</a>) 讨论了使用 RBD 作为 iSCSI/SCSI target 后端的主动-主动集群方案，涉及 LIO 存储管理修改、持久预留、任务管理等。</p></li></ul><h3 id="_2-2-rgw" tabindex="-1">2.2 RGW <a class="header-anchor" href="#_2-2-rgw" aria-label="Permalink to &quot;2.2 RGW&quot;">​</a></h3><ul><li><p><strong>Active-Active 多区域架构</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Active_Active_Arch.html">CDS_Infernalis_Day_1_--<em>RGW</em>-_Active_Arch</a>) 提出将&quot;zone&quot;概念重命名为&quot;zone group&quot;以消除歧义，并设计了每个区域维护独立日志、由 Sync Agent 负责跨区域同步的新架构，支持多区域并发读写。</p></li><li><p><strong>多租户支持</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Multitenancy.html">CDS_Infernalis_Day_1_--<em>RGW</em>-_Multitenancy</a>) 讨论了为 RGW 用户和存储桶引入租户属性的方案，现有用户归入全局租户，新用户继承租户属性，并探讨了与 Keystone 集成及基于角色的认证方案。</p></li><li><p><strong>NFS 导出</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_NFS.html">CDS_Infernalis_Day_1_--<em>RGW</em>-_NFS</a>) 讨论了通过创建高层次 librgw 库、对接 NFS-Ganesha 来实现 RGW 数据的 NFS 导出能力。</p></li><li><p><strong>RGW 架构全面介绍</strong>：<a href="/VideoSummary/posts/2015/2015-MAR-26_--_Ceph_Tech_Talks_-_RGW.html">2015-MAR-26_--<em>Ceph_Tech_Talks</em>-_RGW</a>) Tech Talk 系统介绍了 RGW 的前端、RESTful API、执行层、数据管理、多区域配置等模块，并宣布下一步计划包括主动架构、多租户、对象过期和 NFS 导出。</p></li></ul><h3 id="_2-3-osd-rados" tabindex="-1">2.3 OSD /RADOS <a class="header-anchor" href="#_2-3-osd-rados" aria-label="Permalink to &quot;2.3 OSD /RADOS&quot;">​</a></h3><ul><li><p><strong>NewStore 新存储后端</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Newstore.html">CDS_Infernalis_Day_2.2_--<em>OSD</em>-_Newstore</a>) 提出以 RocksDB 管理事务和键值数据、以 XFS 管理数据块的新架构，通过避免双写消除 journal 开销，支持异步事务提交。</p></li><li><p><strong>EC 池覆盖写</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Erasure_Coding_Pool_Overwrite_Support.html">CDS_Infernalis_Day_1_--<em>OSD</em>-_Erasure_Coding_Pool_Overwrite_Support</a>) 评估了两阶段提交方案（确定性、可预测、类 RAID 行为）作为首选实现路径。</p></li><li><p><strong>Peering 延迟优化</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Peering_Latency.html">CDS_Infernalis_Day_2.2_--<em>OSD</em>-_Peering_Latency</a>) 分析了 pering 过程中多个往返延迟来源，提出基于历史区间预判权威 OSD、客户端驱动读取（client-driven read）等优化方案。</p></li><li><p><strong>Scrub 侵入性降低</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Less_Intrusive_Scrub.html">CDS_Infernalis_Day_1_--<em>OSD</em>-_Less_Intrusive_Scrub</a>) 讨论了随机化 scrub 调度时间、细粒度 scrub 窗口、统一工作队列（unified work queue）、scrub 限速等方案。</p></li><li><p><strong>Scrub 与 Repair 接口</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Scrub_and_Repair.html">CDS_Infernalis_Day_1_--<em>OSD</em>-_Scrub_and_Repair</a>) 讨论了开发 RADOS 接口查询 PG 修复状态、创建命令行工具处理不一致对象的方案。</p></li><li><p><strong>I/O Hints</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_RADOS_I_O_Hints.html">CDS_Infernalis_Day_2.2_--<em>OSD</em>-_RADOS_I_O_Hints</a>) 讨论了在 RBD 和文件系统中传递 I/O 缓存行为提示（如 no-cache、proxy read）的框架，计划在 Hammer 版本中实现。</p></li><li><p><strong>分层存储扩展</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Tiering.html">CDS_Infernalis_Day_2.2_--<em>OSD</em>-_Tiering</a>) 讨论了将冷数据迁移到外部存储系统（其他 Ceph 集群、S3、Glacier）的插件接口设计，以及多级分层存储架构。</p></li><li><p><strong>Cache Tier 改进</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_Cache_Tier_Improvements.html">CDS_Infernalis_Day_2.2_--_Cache_Tier_Improvements</a>) 讨论了基于 I/O 类型（读/写、顺序/随机）进行更精细的 promotion 决策，以及使用近似计数 Bloom 过滤器改进 Hit Set 的方案。</p></li><li><p><strong>LMDB 键值后端</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_LMDB_backend_for_Ceph.html">CDS_Infernalis_Day_2.2_--_LMDB_backendfor_Ceph</a>) 讨论了将 LMDB 作为 OSD 键值存储后端的可行性，以解决 RocksDB 读写放大问题。</p></li></ul><h3 id="_2-4-cephfs" tabindex="-1">2.4 CephFS <a class="header-anchor" href="#_2-4-cephfs" aria-label="Permalink to &quot;2.4 CephFS&quot;">​</a></h3><ul><li><strong>OpenStack 集成与多租户</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_CephFS_OpenStack.html">CDS_Infernalis_Day_1_--_CephFS_OpenStack</a>) 讨论了 CephFS 与 Manila 集成的三种方案（默认驱动、Ganesha 驱动、原生驱动），倾向于 Ganesha 驱动以提供网络隔离和多租户支持，同时讨论了 Swift 兼容性差距。</li></ul><h3 id="_2-5-基础设施与工具" tabindex="-1">2.5 基础设施与工具 <a class="header-anchor" href="#_2-5-基础设施与工具" aria-label="Permalink to &quot;2.5 基础设施与工具&quot;">​</a></h3><ul><li><p><strong>Ceph 插件系统</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Ceph_Plugins.html">CDS_Infernalis_Day_1_--_Ceph_Plugins</a>) 讨论了通用插件加载机制，包括插件版本与 OSD 版本严格匹配、以 C++ 虚拟类定义插件接口、以 OS 包形式分发插件等规范。</p></li><li><p><strong>dm-crypt 密钥管理</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Simple_ceph-mon_dm-crypt_key_management.html">CDS_Infernalis_Day_1_--_Simple_ceph-mon_dm-crypt_key_management</a>) 讨论了使用 LUKS 存储 OSD dm-crypt 密钥、设计可撤销密钥机制、实现 CLI 会话加密的方案。</p></li><li><p><strong>容器化部署</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Ceph_Containers.html">CDS_Infernalis_Day_1_--_Ceph_Containers</a>) 介绍了官方 Ceph Docker 镜像（包含 Monitor、OSD、MDS、RGW 组件）、基于 etcd 的分布式配置方案，以及 Ceph 作为 Kubernetes 存储提供商的集成探索。</p></li><li><p><strong>性能分析框架</strong>：<a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_Ceph_Performance.html">CDS_Infernalis_Day_2.2_--_Ceph_Performance</a>) 讨论了将 COSBench 集成到 CBT（Ceph Benchmarking Tool）、引入语义化 Tracepoint 框架（基于 LTng）、使用 Zipkin 进行分布式追踪的标准化方案。</p></li></ul><hr><h2 id="三、重要决策与里程碑" tabindex="-1">三、重要决策与里程碑 <a class="header-anchor" href="#三、重要决策与里程碑" aria-label="Permalink to &quot;三、重要决策与里程碑&quot;">​</a></h2><p><strong>版本规划</strong></p><ul><li>本季度的 CDS（Ceph Developer Summit）以 <strong>Infernalis</strong> 版本为主题，多个议题均以 Infernalis 周期为交付目标。</li><li>Hammer 版本即将发布，多项功能（如 I/O hints、Cache Tier 写代理改进）计划在 Hammer 中落地。</li></ul><p><strong>重大设计决定</strong></p><table tabindex="0"><thead><tr><th>决策</th><th>内容</th></tr></thead><tbody><tr><td>EC覆盖写方案</td><td>选择两阶段提交作为首选实现路径</td></tr><tr><td>RGW 区域命名</td><td>&quot;zone&quot; 重命名为 &quot;zone group&quot;，消除与数据中心概念的混淆</td></tr><tr><td>NewStore 技术选型</td><td>RocksDB（事务/KV）+ XFS（数据块）的混合架构</td></tr><tr><td>RBD 异步镜像</td><td>基于完整 journal 的异步复制，支持池级别配置</td></tr><tr><td>CephFS-Manila 集成</td><td>优先推进 Ganesha 驱动方案</td></tr><tr><td>Calamari 重命名</td><td>Calamari 客户端重命名为 <strong>Rana</strong>，采用 MIT 许可证，详见 <a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Calamari_Discussion.html">CDS_Infernalis_Day_1_--_Calamari_Discussion</a>)</td></tr></tbody></table><p><strong>治理里程碑</strong></p><p><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Community_Governance.html">CDS_Infernalis_Day_1_--_Community_Governance</a>) 讨论了 Ceph 项目向自我治理演进的路线图，计划建立包含董事会、技术委员会和用户委员会的三层治理结构，Red Hat 承诺提供更多社区资源（测试实验室、硬件等）。</p><hr><h2 id="四、社区动态" tabindex="-1">四、社区动态 <a class="header-anchor" href="#四、社区动态" aria-label="Permalink to &quot;四、社区动态&quot;">​</a></h2><p><strong>Tech Talk 系列</strong></p><p>本季度 Ceph Tech Talk 系列持续举办，覆盖核心组件的深度技术解析：</p><ul><li>1月：<a href="/VideoSummary/posts/2015/2015-JAN-22_--_Ceph_Tech_Talk_-_RADOS.html">2015-JAN-22_--<em>Ceph_Tech_Talk</em>-_RADOS</a>) — RADOS 内部架构，涵盖 librados、CRUSH、缓存分层、Erasure Coding</li><li>2月：<a href="/VideoSummary/posts/2015/2015-FEB-26_--_Ceph_Tech_Talks_-_RBD.html">2015-FEB-26_--<em>Ceph_TechTalks</em>-_RBD</a>) — RBD 技术深度解析，包括快照、克隆、I/O 路径</li><li>3月：<a href="/VideoSummary/posts/2015/2015-MAR-26_--_Ceph_Tech_Talks_-_RGW.html">2015-MAR-26_--<em>Ceph_Tech_Talks</em>-_RGW</a>) — RGW 架构与工作原理，宣布 4 月将举办 Calamari 专题</li></ul><p><strong>Ceph Day London</strong></p><p>本季度举办了 Ceph Day London，来自 IBM 和荷兰社区的成员分享了实际部署经验：</p><ul><li><a href="/VideoSummary/posts/2015/IBM_@_Ceph_Day_London.html">IBM_@_Ceph_Day_London</a>)：IBM 研究部门分享了在 OpenStack 环境和 SoftLayer 云平台上的 Ceph 部署实践，包括 SD/HDD 混合存储配置和跨数据中心管理规划。</li><li><a href="/VideoSummary/posts/2015/Wido_@_Ceph_Day_London.html">Wido_@_Ceph_Day_London</a>)：荷兰社区成员 Wido 分享了多年 Ceph 部署最佳实践，强调优先关注 I/O 性能而非容量、使用 SSD 作为 journal 盘、避免过多 PG 等实战经验。</li></ul><p><strong>CDS Infernalis</strong></p><p>本季度举办了 CDS Infernalis（Ceph Developer Summit），分两天进行，涵盖 OSD、RBD、RGW、CephFS、容器、治理等多个专题，是本季度社区活动的核心。</p><hr><h2 id="五、下季度展望" tabindex="-1">五、下季度展望 <a class="header-anchor" href="#五、下季度展望" aria-label="Permalink to &quot;五、下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2015 Q2 将重点推进以下方向：</p><ol><li><p><strong>Hammer 版本发布</strong>：I/O hints 框架、Cache Tier 写代理改进、scrub 优化等功能预计随 Hammer 发布落地。</p></li><li><p><strong>RBD 异步镜像原型实现</strong>：journal 模块设计和异步复制功能的初步实现将是 RBD 方向的核心工作。</p></li><li><p><strong>RGW Active-Active 架构推进</strong>：同步代理改进、对象版本控制重构、多租户初步实现预计进入开发阶段。</p></li><li><p><strong>NewStore 基准测试</strong>：新存储后端完成 omap 实现和异步提交后，将进入性能基准测试阶段。</p></li><li><p><strong>Calamari → Rana 迁移</strong>：Rana 首个版本预计在 Hammer 发布后约一个月推出。</p></li><li><p><strong>CephFS 稳定化与 Manila 集成</strong>：Ganesha 驱动开发和 OpenStack 第三方测试环境搭建将持续推进。</p></li><li><p><strong>EC 覆盖写原型</strong>：两阶段提交方案的原型实现预计启动。</p></li><li><p><strong>容器化部署完善</strong>：官方 Docker 镜像多版本分支持和 Kubernetes 集成方案将进一步完善。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2015/2015-FEB-26_--_Ceph_Tech_Talks_-_RBD.html">2015-FEB-26 -- Ceph Tech Talks: RBD</a>)</li><li><a href="/VideoSummary/posts/2015/2015-JAN-22_--_Ceph_Tech_Talk_-_RADOS.html">2015-JAN-22 -- Ceph Tech Talk: RADOS</a>)</li><li><a href="/VideoSummary/posts/2015/2015-MAR-26_--_Ceph_Tech_Talks_-_RGW.html">2015-MAR-26 -- Ceph Tech Talks: RGW</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Accelio_XIO_Integration_with_kernel_RBD.html">CDS Infernalis (Day 1) -- Accelio XIO Integration with kernel RBD</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Calamari_Discussion.html">CDS Infernalis (Day 1) -- Calamari Discussion</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_CephFS_OpenStack.html">CDS Infernalis (Day 1) -- CephFS &amp;&amp; OpenStack</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Ceph_Containers.html">CDS Infernalis (Day 1) -- Ceph &amp;&amp; Containers</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Ceph_Plugins.html">CDS Infernalis (Day 1) -- Ceph Plugins</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Clustered_SCSI_Target_using_RBD.html">CDS Infernalis (Day 1) -- Clustered SCSI Target using RBD</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Community_Governance.html">CDS Infernalis (Day 1) -- Community &amp;&amp; Governance</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Erasure_Coding_Pool_Overwrite_Support.html">CDS Infernalis (Day 1) -- OSD: Erasure Coding Pool Overwrite Support</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Less_Intrusive_Scrub.html">CDS Infernalis (Day 1) -- OSD: Less Intrusive Scrub</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Scrub_and_Repair.html">CDS Infernalis (Day 1) -- OSD: Scrub and Repair</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RBD_-_Async_Mirroring.html">CDS Infernalis (Day 1) -- RBD: Async Mirroring</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Active_Active_Arch.html">CDS Infernalis (Day 1) -- RGW: Active/Active Arch</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Multitenancy.html">CDS Infernalis (Day 1) -- RGW: Multitenancy</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_RGW_-_NFS.html">CDS Infernalis (Day 1) -- RGW: NFS</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_1_--_Simple_ceph-mon_dm-crypt_key_management.html">CDS Infernalis (Day 1) -- Simple ceph-mon dm-crypt key management</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_Cache_Tier_Improvements.html">CDS Infernalis (Day 2.2) -- Cache Tier Improvements</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_Ceph_Performance.html">CDS Infernalis (Day 2.2) -- Ceph Performance</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_LMDB_backend_for_Ceph.html">CDS Infernalis (Day 2.2) -- LMDB backend for Ceph</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Newstore.html">CDS Infernalis (Day 2.2) -- OSD: Newstore</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Peering_Latency.html">CDS Infernalis (Day 2.2) -- OSD: Peering / Latency</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_RADOS_I_O_Hints.html">CDS Infernalis (Day 2.2) -- OSD: RADOS I/O Hints</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Tiering.html">CDS Infernalis (Day 2.2) -- OSD: Tiering</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Transactions.html">CDS Infernalis (Day 2.2) -- OSD: Transactions</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Add_metadata_mechanism_to_LibRBD.html">CDS Infernalis (Day 2.2) -- RBD: Add metadata mechanism to LibRBD</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Kernel_RBD_client_supports_copy-on-read.html">CDS Infernalis (Day 2.2) -- RBD: Kernel RBD client supports copy-on-read</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_export_diff_between_clone_parent.html">CDS Infernalis (Day 2.2) -- RBD: export diff between clone/parent</a>)</li><li><a href="/VideoSummary/posts/2015/IBM_@_Ceph_Day_London.html">IBM @ Ceph Day London</a>)</li><li><a href="/VideoSummary/posts/2015/Wido_@_Ceph_Day_London.html">Wido @ Ceph Day London</a>)</li></ul>',52)])])}const S=a(i,[["render",t]]);export{h as __pageData,S as default};
